python3 -c "
import ast
import os

base = '/run/host/run/media/rana/DEV/code/Experment/lumos/tools/fastapi-cpp/astraapi'
errors = []
for root, dirs, files in os.walk(base):
    dirs[:] = [d for d in dirs if d != '__pycache__']
    for fname in files:
        if fname.endswith('.py'):
            path = os.path.join(root, fname)
            with open(path) as f:
                src = f.read()
